{
  "avaliacoes": [
    {
      "id": "E22e5eaf0b8f99fdc",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em FPSOs, a transferência para navio aliviador é realizada por aproximação/emparelhamento, conexão por mangotes de offloading e bombeio do fluido, o que torna os mangotes elementos centrais da operação de alívio.",
          "trechos": [
            "E22e5eaf0b8f99fdc:699:1399"
          ],
          "condicoes": [
            "Aplicável ao contexto de alívio/offloading entre FPSO, monobóia ou FSO e navio aliviador."
          ],
          "limites": [
            "O trecho descreve a configuração geral da operação, sem detalhar critérios de teste, inspeção ou armazenamento."
          ]
        },
        {
          "proposicao": "A utilização de FPSO com armazenamento próprio pode tornar desnecessários sistemas permanentes de escoamento e estruturas auxiliares de armazenamento, reduzindo pontos potenciais de falha do sistema de produção como um todo.",
          "trechos": [
            "E22e5eaf0b8f99fdc:0:699"
          ],
          "condicoes": [
            "Relaciona-se às características do tipo de unidade citado no trecho."
          ],
          "limites": [
            "Não quantifica redução de risco nem demonstra causalidade universal para todas as configurações."
          ]
        },
        {
          "proposicao": "Os mangotes de offloading são descritos como dutos flexíveis de camadas aderentes, nos quais as camadas internas ficam embebidas em matriz polimérica e solidarizadas por vulcanização, sem deslizamento relativo interno sob esforços operacionais, em contraste com dutos flexíveis não aderentes.",
          "trechos": [
            "E22e5eaf0b8f99fdc:1399:2099",
            "E22e5eaf0b8f99fdc:2099:2290"
          ],
          "condicoes": [
            "Comparação feita com dutos flexíveis não aderentes empregados na indústria offshore."
          ],
          "limites": [
            "O trecho é descritivo de construção e comportamento estrutural; não informa limites operacionais, ensaios ou critérios de aceitação."
          ]
        }
      ]
    },
    {
      "id": "E3530141218fd6dd0",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na sequência operacional descrita, após o posicionamento do navio aliviador e o travamento do sistema de amarração, realiza-se a conexão do mangote e somente então o sistema fica pronto para abertura de válvulas e início da transferência.",
          "trechos": [
            "E3530141218fd6dd0:698:1397"
          ],
          "condicoes": [
            "Dentro da sequência operacional de offloading apresentada na fonte."
          ],
          "limites": [
            "A fonte descreve uma sequência de operação, não uma norma universal aplicável a qualquer arranjo de offloading."
          ]
        },
        {
          "proposicao": "Antes do início da transferência, a linha de transferência deve ser pressurizada; para manter a pressão na linha, a válvula de transferência permanece aberta e a válvula coletora do navio aliviador fechada.",
          "trechos": [
            "E3530141218fd6dd0:698:1397",
            "E3530141218fd6dd0:1397:2091"
          ],
          "condicoes": [
            "Refere-se ao procedimento operacional descrito para a etapa pré-transferência."
          ],
          "limites": [
            "O trecho não informa pressão-alvo, método de teste de estanqueidade ou critérios de aceitação."
          ]
        },
        {
          "proposicao": "No começo e no término do processo, as válvulas devem ser reguladas para baixa vazão; ao final da transferência, essa condição é destacada para evitar transbordamento do tanque, seguindo-se desconexão, envio do mangote e desamarração.",
          "trechos": [
            "E3530141218fd6dd0:1397:2091"
          ],
          "condicoes": [
            "Aplicável às fases inicial e final da transferência, conforme o procedimento descrito."
          ],
          "limites": [
            "A fonte não detalha drenagem interna da mangueira nem procedimentos de lavagem ou armazenamento."
          ]
        }
      ]
    },
    {
      "id": "E630d301bf8e68193",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Sistemas de offloading com mangueiras devem prever meios de bloqueio/desligamento para minimizar perda de hidrocarbonetos em caso de ruptura de mangueira/tubulação ou deslocamento do navio aliviador com desconexão da mangueira.",
          "trechos": [
            "E630d301bf8e68193:0:696",
            "E630d301bf8e68193:696:1396"
          ],
          "condicoes": [
            "No contexto de tandem offloading e de falhas como ruptura ou saída de posição do navio aliviador."
          ],
          "limites": [
            "Fonte vinculada a orientação e abordagem de inspeção do HSE do Reino Unido; não deve ser convertida automaticamente em requisito brasileiro."
          ]
        },
        {
          "proposicao": "O diâmetro do conjunto de mangueiras deve ser compatível com a vazão de projeto do offloading para não exceder limites de velocidade do fluido definidos pelo fabricante.",
          "trechos": [
            "E630d301bf8e68193:696:1396"
          ],
          "condicoes": [
            "Depende da vazão de projeto e dos limites especificados pelo fabricante."
          ],
          "limites": [
            "A fonte não fornece valores numéricos de velocidade nem critérios de dimensionamento."
          ]
        },
        {
          "proposicao": "Após o offloading, deve haver capacidade adequada de nitrogênio ou gás inerte para deslocar o líquido da mangueira e auxiliar sua recuperação, porque líquido remanescente aumenta peso e desgaste da mangueira e dos equipamentos de recolhimento; além disso, inspeções rotineiras devem buscar sinais de desgaste e deformação.",
          "trechos": [
            "E630d301bf8e68193:696:1396",
            "E630d301bf8e68193:1396:2095",
            "E630d301bf8e68193:2095:2204"
          ],
          "condicoes": [
            "Aplicável à etapa pós-offloading e ao programa rotineiro de inspeção."
          ],
          "limites": [
            "A fonte não define periodicidade de inspeção, volume de gás ou método específico de aceitação."
          ]
        }
      ]
    },
    {
      "id": "Ec2bf00975f3bcfae",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A operação de offloading é apresentada como transferência de óleo entre FPSO e navio aliviador por meio de linha de mangotes, após armazenamento do petróleo no próprio FPSO.",
          "trechos": [
            "Ec2bf00975f3bcfae:0:699"
          ],
          "condicoes": [
            "No arranjo operacional descrito para FPSO e navio aliviador."
          ],
          "limites": [
            "O trecho é introdutório e não detalha critérios de segurança ou desempenho."
          ]
        },
        {
          "proposicao": "As etapas descritas incluem alinhamento das embarcações, amarração por cabos-guia, conexão do mangote de transferência e início do bombeamento do óleo.",
          "trechos": [
            "Ec2bf00975f3bcfae:699:1395",
            "Ec2bf00975f3bcfae:1395:2094"
          ],
          "condicoes": [
            "Sequência apresentada como principais etapas da operação."
          ],
          "limites": [
            "Não informa testes prévios, pressurização da linha ou critérios para autorização de início."
          ]
        },
        {
          "proposicao": "Ao final da operação, o mangote é lavado e recolhido, em seguida ocorre a desconexão dos cabos de amarração e a partida do navio aliviador para o terminal de descarga.",
          "trechos": [
            "Ec2bf00975f3bcfae:1395:2094"
          ],
          "condicoes": [
            "Aplicável à fase de encerramento da operação conforme a descrição da fonte."
          ],
          "limites": [
            "A fonte menciona lavagem e recolhimento, mas não especifica fluido, sequência detalhada de drenagem ou condições de armazenamento."
          ]
        }
      ]
    },
    {
      "id": "Eb2eb0a4e6c18ea84",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em incidente relatado pela ANP, houve derramamento ao mar durante offloading devido à ruptura de fuse-screws do QRF, componente do sistema IHTP entre o carretel e a mangueira de offloading.",
          "trechos": [
            "Eb2eb0a4e6c18ea84:0:696"
          ],
          "condicoes": [
            "Relativo ao evento específico investigado no alerta de segurança."
          ],
          "limites": [
            "Trata-se de um caso investigado, não de demonstração universal sobre todos os sistemas QRF/IHTP."
          ]
        },
        {
          "proposicao": "A investigação apontou falhas de gestão de mudanças associadas a procedimento de recolhimento/puxada das mangueiras executado de forma diferente do manual do fornecedor e à não atualização do HAZOP após alteração que removeu uma salvaguarda de baixa pressão.",
          "trechos": [
            "Eb2eb0a4e6c18ea84:696:1393",
            "Eb2eb0a4e6c18ea84:1393:2092"
          ],
          "condicoes": [
            "Conclusões restritas ao evento analisado pela investigação."
          ],
          "limites": [
            "O trecho não estabelece frequência dessas falhas nem sua prevalência na indústria."
          ]
        },
        {
          "proposicao": "Foram também identificadas lacunas documentais e de projeto, incluindo ausência de recomendações de inspeção e manutenção do IHTP e falta de alerta sobre a posição em que o conjunto deveria permanecer no carretel, além de ausência de requisito de intertravamento para posição correta do reel durante o offloading.",
          "trechos": [
            "Eb2eb0a4e6c18ea84:1393:2092"
          ],
          "condicoes": [
            "Referente às causas identificadas na investigação do alerta."
          ],
          "limites": [
            "Não informa solução validada, eficácia de correções nem converte automaticamente essas observações em obrigação regulatória geral."
          ]
        }
      ]
    },
    {
      "id": "Ec9ec7e40f2fc6fef",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "As estações de alívio em FPSOs podem ser divididas entre facilidades de bombeio e transferência de óleo e facilidades de amarração do navio aliviador.",
          "trechos": [
            "Ec9ec7e40f2fc6fef:0:691"
          ],
          "condicoes": [
            "No contexto de sistemas de descarregamento/estações de alívio em operações de offloading."
          ],
          "limites": [
            "A divisão é funcional e não detalha todos os equipamentos de cada subsistema."
          ]
        },
        {
          "proposicao": "Projeto, fabricação e manutenção dessas estações devem atender às operações de offshore loading em tandem com mangote de transferência flutuante, e operadoras podem especificar soluções adicionais ao mínimo requerido por entidades setoriais e classificadoras, priorizando soluções comprovadas em campo devido à criticidade da confiabilidade para continuidade da produção.",
          "trechos": [
            "Ec9ec7e40f2fc6fef:691:1384"
          ],
          "condicoes": [
            "Segundo a descrição da fonte, em operações tandem com mangote flutuante.",
            "As exigências adicionais são atribuídas, em geral, às companhias operadoras."
          ],
          "limites": [
            "O trecho não identifica quais requisitos mínimos nem quais soluções comprovadas seriam exigidos em cada caso."
          ]
        },
        {
          "proposicao": "A configuração da estação de offloading mencionada destaca carretel do cabo de amarração e carretel do mangote, indicando integração física entre subsistemas de amarração e transferência.",
          "trechos": [
            "Ec9ec7e40f2fc6fef:1384:2083"
          ],
          "condicoes": [
            "Descrição associada à figura de estação de offloading de popa de FPSO de aproamento fixo."
          ],
          "limites": [
            "A fonte depende de figura referenciada e não detalha arranjos alternativos nem condições de operação."
          ]
        }
      ]
    }
  ],
